def parse_csv_line(line):
    # Handle empty line
    if line == '':
        return ['']
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # Start of quoted field
            i += 1  # skip opening quote
            field = ''
            while i < n:
                if line[i] == '"':
                    # Check for escaped quote
                    if i + 1 < n and line[i + 1] == '"':
                        field += '"'
                        i += 2  # consume both quotes
                    else:
                        # Closing quote
                        i += 1  # skip closing quote
                        # After closing quote must be comma or end
                        if i < n and line[i] != ',':
                            raise ValueError("invalid character after closing quote")
                        # Skip comma if present
                        if i < n and line[i] == ',':
                            i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end without closing quote
                raise ValueError("missing closing quote")
            fields.append(field)
        else:
            # Unquoted field
            field = ''
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("double quote in unquoted field")
                field += line[i]
                i += 1
            # Skip comma if present
            if i < n and line[i] == ',':
                i += 1
            fields.append(field)
    return fields


